fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Use iterators to zip all three vectors together
    dst.into_iter()
        .zip(src.into_iter())
        .zip(mask.into_iter())
        .map(|((d, s), m)| if m { s } else { d })
        .collect()
}